import React, { useContext, useEffect, useState } from "react";
import { GoogleLogin } from "@react-oauth/google";
import { useNavigate } from "react-router-dom";
import { jwtDecode } from "jwt-decode";
import axios from "axios";

import { UserContext } from "./UserContext";
import "./LoginPage.css";
import "./base.css";

const LoginPage = () => {
  const navigate = useNavigate();
  const { user, login, logout } = useContext(UserContext);
  const [youtubeConnected, setYoutubeConnected] = useState(false);

  // Check if user is already logged in & navigate to home
  useEffect(() => {
    if (user) {
      // Check YouTube authorization status
      checkYouTubeAuth();
    }
  }, [user]);

  // Check YouTube auth status when user logs in
  const checkYouTubeAuth = async () => {
    try {
      const response = await axios.get('/api/youtube/check-auth/', {
        headers: {
          Authorization: `Bearer ${localStorage.getItem('authToken')}`
        }
      });

      setYoutubeConnected(response.data.is_authorized);
    } catch (error) {
      console.error('Error checking YouTube auth:', error);
      setYoutubeConnected(false);
    }
  };

  // Handle Google Login Success
  const handleGoogleLoginSuccess = (response) => {
    try {
      const decodedUser = jwtDecode(response.credential); // Decode the token
      console.log("Google Login Success:", decodedUser);

      // Save user in context & localStorage
      login(decodedUser);

      // Redirect to Home Page
      navigate("/home");
    } catch (error) {
      console.error("Error decoding Google token:", error);
    }
  };

  // Handle Google Login Failure
  const handleGoogleLoginFailure = () => {
    console.log("Google Login Failed");
  };

  // Handle YouTube Authorization
  const handleYouTubeAuth = () => {
    // Redirect to Django backend auth endpoint
    window.location.href = '/youtube-auth-callback';
  };

  return (
    <div className="login-page">
      <header className="header">
        <h1 className="logo">
          <span className="bold">Channel-</span>
          <span className="highlight">IQ</span>
        </h1>
        <nav className="nav">
          {user && (
            <button className="sign-out" onClick={logout}>
              Logout
            </button>
          )}
        </nav>
      </header>

      <div className="login-container">
        <div className="left-panel">
          <h1>
            Channel-<span className="highlight">IQ</span>
          </h1>
          <p>
            Turn your long videos into <span className="highlight">VIRAL</span> short clips.
          </p>
          <ul>
            <li>✔ AI SEO</li>
            <li>✔ Auto Caption</li>
            <li>✔ Auto Clipping</li>
            <li>✔ Quality Enhancer</li>
            <li>✔ Sound Improvement</li>
            <li>✔ YouTube Upload</li>
          </ul>
        </div>

        <div className="right-panel">
          {!user ? (
            <>
              <h2>Login to your account</h2>
              <div className="login-button-container">
                <GoogleLogin
                  onSuccess={handleGoogleLoginSuccess}
                  onError={handleGoogleLoginFailure}
                />
              </div>
            </>
          ) : (
            <>
              <h2>Welcome, {user.name}</h2>
              <div className="account-status">
                <div className="status-item">
                  <span>Google Account:</span>
                  <span className="status connected">Connected</span>
                </div>

                <div className="status-item">
                  <span>YouTube:</span>
                  {youtubeConnected ? (
                    <span className="status connected">Connected</span>
                  ) : (
                    <>
                      <span className="status not-connected">Not Connected</span>
                      <button className="connect-youtube" onClick={handleYouTubeAuth}>
                        Connect
                      </button>
                    </>
                  )}
                </div>
              </div>

              <div className="action-buttons">
                <button className="continue-button" onClick={() => navigate('/home')}>
                  Go to Dashboard
                </button>
                <button className="logout-button" onClick={logout}>
                  Logout
                </button>
              </div>
            </>
          )}
        </div>
      </div>
    </div>
  );
};

export default LoginPage;
